136	  }
137	  printf("\n");
138	  printf("src_ip_category_cnt=%d\n", src_ip_category_cnt);
139	  for (i = 0; i < src_ip_category_cnt; i++) {
140	    printf("%s/invert=%s, ", src_ip_category_array[i].category.c_str(), src_ip_category_array[i].invert ? "true" : "false");
141	  }
142	  printf("\n");
143	  printf("in_ip_cnt=%d\n", in_ip_cnt);
